[{"type":"text","text":"<script>
import listMixins from '@/mixins/listMixins'
import template from '@/mixins/ListTemplate.js'
import { resolveServerAssetUrl } from '@/utils/resolveServerAssetUrl.js'

const defaultMonth = () => dayjs().subtract(1, 'month').format('YYYY-MM')

export default {
  template,
  name: 'PubRecBankFile',
  mixins: [listMixins],
  data() {
    return {
      primaryKey: 'bankFileId',
      moduleName: 'benefit',
      businessName: 'pubRecBankFile',
      tableData: [],
      queryParams: {
        pageNum: 1,
        pageSize: 10,
        keyword: undefined,
        reconciliationMonthBegin: defaultMonth(),
        reconciliationMonthEnd: defaultMonth()
      }
    }
  },
  computed: {
    formItems() {
      return [
        {
          label: '关键字',
          model: 'keyword',
          type: 'input',
          attrs: {
            placeholder: '请输入关键字'
          }
        },
        {
          label: '月份范围',
          model: 'dateRange',
          type: 'date',
          attrs: {
            range: true,
            start: 'reconciliationMonthBegin',
            end: 'reconciliationMonthEnd',
            type: 'monthrange',
            format: 'yyyy-MM',
            'value-format': 'yyyy-MM',
            'start-placeholder': '开始日期',
            'end-placeholder': '结束日期'
          }
        }
      ]
    },
    columns() {
      return [
        {
          type: 'text',
          label: '小区名称',
          prop: 'projectName'
        },
        {
          type: 'text',
          label: '管理账号',
          prop: 'regulatoryAccount'
        },
        {
          type: 'text',
          label: '管理银行',
          prop: 'regulatoryBankName'
        },
        {
          type: 'text',
          label: '管理账户名称',
          prop: 'regulatoryAccountName'
        },
        {
          type: 'text',
          label: '月份',
          prop: 'reconciliationMonth'
"}]

[{"type":"text","text":"        }
      ]
    },
    operationButtons() {
      return []
    },
    buttons() {
      return [
        {
          label: '下载',
          permission: false,
          attrs: {
            type: 'text'
          },
          function: this.handleDownload
        }
      ]
    }
  },
  methods: {
    handleDownload({ filePath, fileName }) {
      if (!filePath) {
        this.msgWarning('暂无文件可下载')
        return
      }
      fetch(resolveServerAssetUrl(filePath))
        .then((res) => res.blob())
        .then((blob) => {
          const elink = document.createElement('a')
          elink.download = fileName
          elink.href = URL.createObjectURL(blob)
          document.body.appendChild(elink)
          elink.click()
          URL.revokeObjectURL(elink.href)
          document.body.removeChild(elink)
        })
    }
  }
}
</script>
"}]
